	revision := captureSelectedExecutionSourceRevision(t, db, sourceRunID)
	forkOrigin, err := storerunlifecycle.ForkMaterializationRunOrigin(sourceRunID, storerunlifecycle.ForkOriginPointEvent, revision, forkEventID)
	if err != nil {
		t.Fatal(err)
	}
