	defer servedDB.Close()
	standaloneDB, err := sql.Open("postgres", dsn)
	if err != nil {
		t.Fatalf("open standalone PostgreSQL handle: %v", err)
	}
	defer standaloneDB.Close()
	if err := servedDB.PingContext(ctx); err != nil {
		t.Fatalf("ping served PostgreSQL handle: %v", err)
	}
	if err := standaloneDB.PingContext(ctx); err != nil {
		t.Fatalf("ping standalone PostgreSQL handle: %v", err)
	}
	servedStore := storetest.AdmitPostgresRuntimeStore(t, servedDB)
	standaloneStore := storetest.AdmitPostgresRuntimeStore(t, standaloneDB)
	processCapability := selectedContractTestProcessCapability(t, ctx, servedStore)
	fixtureValue, _ := runForkTestWorkFixtures.Load(t)
	process := fixtureValue.(*runForkTestWorkFixture).process
	before, err := storetest.ReadSelectedForkApplicationStorageSnapshot(ctx, servedStore)
	if err != nil {
		t.Fatal(err)
	}
	foreignOwner := newSelectedContractExecutionOwnerForTest(t, standaloneStore)
	if err := foreignOwner.BindSelectedProcess(ctx, process, processCapability); err != nil {
		t.Fatal(err)
	}
	if _, err := foreignOwner.RecoverSelectedForkContexts(ctx, runtimeeffects.NewRecoveryRequest(time.Now().UTC(), executionposture.Live), SelectedForkRecoveryEnvironment{}); !errors.Is(err, runtimestartupownership.ErrProcessNotCurrent) {
		t.Fatalf("foreign store borrowed native process permission: %v", err)
	}
	after, err := storetest.ReadSelectedForkApplicationStorageSnapshot(ctx, servedStore)
	if err != nil || !reflect.DeepEqual(before, after) {
		t.Fatalf("foreign-store refusal changed storage: %v", err)
	}
	if err := processCapability.ProveCurrent(ctx); err != nil {
		t.Fatalf("foreign-store refusal retired the native owner: %v", err)
	}
	fixedPlan, err := servedStore.PlanRunFork(ctx, runfork.RunForkPlanRequest{SourceRunID: sourceRunID, At: forkEventID})
	if err != nil {
		t.Fatal(err)
	}

	selection := runfork.RunForkContractSelection{
		Mode: "selected_contracts",
	}
	selectedSource := testSelectedSource(selection)
	deferredWorkAdmission := selectedContractDeferredWorkAdmissionForTest(t, sourceRunID, forkEventID, selectedSource)
	admission := runfork.RunForkSelectedContractExecutionAdmission{
		Owner:                      runfork.RunForkSelectedContractExecutionAdmissionOwner,
		FutureExecutionOwner:       runfork.RunForkSelectedContractExecutionOwner,
		NonMutating:                true,
		ExecutionSupported:         false,
		ForkRunID:                  forkRunID,
		SourceRunID:                sourceRunID,
		ForkPoint:                  fixedPlan.ForkPoint,
		ForkEventID:                forkEventID,
		ContractSelection:          selection,
		ContractBindingOwner:       runfork.RunForkSelectedContractBindingOwner,
		AdmissionOwner:             runfork.RunForkContractFrontierAdmissionOwner,
		AdmissionUse:               runfork.RunForkSelectedContractExecutionAdmissionUseDurableBinding,
		ExecutionModelOwner:        runfork.RunForkSelectedContractExecutionModelOwner,
		DeferredWorkAdmissionOwner: runfork.RunForkSelectedContractDeferredWorkAdmissionOwner,
		SourceWorkflowName:         "workflow",
		SourceWorkflowVersion:      "v1",
	}
	planning := runfork.RunForkSelectedContractRecipientPlanning{
		Owner:                      runfork.RunForkSelectedContractRecipientPlanningOwner,
		FutureExecutionOwner:       runfork.RunForkSelectedContractExecutionOwner,
		NonMutating:                true,
		RecipientPlanningSupported: true,
		ContractSelection:          selection,
	}
	baseRequest := publishSelectedContractForkEventsRequest{
		Admission: admission,
		LoadedSource: LoadedSelectedContractSource{
			Selection:               selection,
			Source:                  selectedSource,
			SourceArtifactFact:      testEphemeralSourceArtifactFact(runForkTestBundleHash),
			EffectiveSourceIdentity: testEffectiveSourceIdentity(testEphemeralSourceArtifactFact(runForkTestBundleHash)),
		},
		RecipientPlanning:     planning,
		SourceRunID:           sourceRunID,
		ForkRunID:             forkRunID,
		ForkEventID:           forkEventID,
		SourceEvents:          []string{forkEventID},
		ExecutionOwner:        runfork.RunForkSelectedContractExecutionOwner,
		DeferredWorkAdmission: deferredWorkAdmission,
		SourcePlan:            fixedPlan,
		AgentRuntime: selectedContractAgentRuntimePlan{Options: SelectedContractAgentRuntimeOptions{
			ExecutionPosture:  executionposture.Live,
			ProcessCapability: processCapability,
			Config:            &config.Config{LLM: config.LLMConfig{Backend: llmselection.BackendAnthropic}},
		}},
	}
	targetIdentity := selectedContractTestAgentIdentityForRun(t, forkRunID, "selected-agent", "selected-authority-race")
	targetConfig := selectedExecutionFixtureAgentConfig(t, targetIdentity)
	profile, err := llmselection.ResolveLiveBackend(llmselection.BackendAnthropic)
	if err != nil {
		t.Fatal(err)
	}
	resolved, err := runtimellm.ResolveAgentExecution(executionposture.Live, profile, nil, targetConfig)
	if err != nil {
		t.Fatal(err)
	}
	targetConfig = resolved.Actor
	targetPlan, err := targetIdentity.Plan()
	if err != nil {
		t.Fatal(err)
	}
	targetRevision, err := runtimemanager.AgentConfigPlanRevision(targetConfig, targetPlan)
	if err != nil {
		t.Fatal(err)
	}
	baseRequest.AgentRuntime.Declarations, err = runtimeagenttopology.NewSelectedDeclarationPlan(runForkTestBundleHash, []runtimeagenttopology.DesiredAgent{{
		Identity: targetPlan, ConfigRevision: targetRevision, Source: runtimeagenttopology.SourceCoordinate{BundleHash: runForkTestBundleHash},
	}})
	if err != nil {
		t.Fatal(err)
	}
	prospectiveConfig := targetConfig
	prospectiveConfig.Identity = agentidentity.Identity{}
	baseRequest.AgentRuntime.Blueprints = []runtimemanager.AgentMaterializationBlueprint{{Identity: targetPlan, Config: prospectiveConfig}}
	baseRequest.AgentRuntime.Records = []runtimemanager.PersistedAgent{{Config: targetConfig}}
	ctx = runtimeauthoractivity.WithScope(ctx, runtimeauthoractivity.BundleScope(
		runForkTestRuntimeInstanceID,
		baseRequest.LoadedSource.SourceArtifactFact.BundleHash(),
	))
	type contenderResult struct {
		surface   string
		container selectedContractForkLocalRuntimeContainer
		store     *store.PostgresStore
		owner     SelectedContractExecutionOwner
		prepared  *PreparedSelectedFork
		err       error
	}
	start := make(chan struct{})
	defer func() {
		select {
		case <-start:
		default:
			close(start)
		}
	}()
	results := make(chan contenderResult, 2)
	contenders := []struct {
		surface string
		store   *store.PostgresStore
	}{
		{surface: "served", store: servedStore},
		{surface: "standalone", store: servedStore},
	}
	// Two component contexts compete inside one legitimately acquired process.
	// Neither borrows another store's capability or shares a local context cache.
	var previousOwner SelectedContractExecutionOwner
	for _, contender := range contenders {
		contender := contender
		operation := selectedContractOperationForTest(t, ctx)
		owner := newSelectedContractExecutionOwnerForTest(t, contender.store)
		if previousOwner.ports != nil && previousOwner.ports.contexts == owner.ports.contexts {
			t.Fatal("served and standalone contenders share their local context registry")
		}
		previousOwner = owner
		if err := owner.BindSelectedProcess(ctx, process, processCapability); err != nil {
			t.Fatal(err)
		}
		if _, err := owner.RecoverSelectedForkContexts(ctx, runtimeeffects.NewRecoveryRequest(time.Now().UTC(), executionposture.Live), SelectedForkRecoveryEnvironment{}); err != nil {
			t.Fatal(err)
		}
		prepared, err := prepareSelectedFork(ctx, operation, owner.ports, baseRequest.LoadedSource, fixedPlan, runfork.RunForkContractFrontierAdmission{}, planning, baseRequest.AgentRuntime)
		if err != nil {
			t.Fatal(err)
		}
		go func() {
			<-start
			req := baseRequest
			req.Operation = operation
			req.Owner = owner
			req.Prepared = prepared
			container, buildErr := buildSelectedContractForkLocalRuntimeContainer(ctx, req)
			results <- contenderResult{surface: contender.surface, container: container, store: contender.store, owner: owner, prepared: prepared, err: buildErr}
		}()
	}
	close(start)
	first, second := <-results, <-results
	var winner contenderResult
	var loser contenderResult
	if first.err == nil {
		winner, loser = first, second
	} else {
		winner, loser = second, first
	}
	if winner.err != nil || loser.err == nil {
		t.Fatalf("served/standalone authority race first=%s/%v second=%s/%v, want exactly one winner", first.surface, first.err, second.surface, second.err)
	}
	if winner.surface == loser.surface {
		t.Fatalf("served/standalone authority race returned duplicate surface %q", winner.surface)
	}
	if errors.Is(loser.err, runtimestartupownership.ErrProcessNotCurrent) || !strings.Contains(loser.err.Error(), "already has current execution") {
		t.Fatalf("losing %s container did not reach durable selected-execution contention: %v", loser.surface, loser.err)
	}
	proof := winner.container.Proof()
	if proof.RuntimeExecutionID == "" || proof.RuntimeGeneration != 1 || proof.AuthorityExecutionOwner == "" {
		t.Fatalf("winning %s authority proof = %#v", winner.surface, proof)
	}

	authority := winner.container.authority
	grantRequest := baseRequest
	grantRequest.Prepared = winner.prepared
	grantRequest.Owner = winner.owner
	grantRequest.AgentRuntime.Options.ProcessCapability = processCapability
	grant, err := issueSelectedContractAgentRuntimeGenerationGrant(ctx, grantRequest, authority)
	if err != nil {
		t.Fatal(err)
	}
	topology, err := runtimeagenttopology.SelectedDeclarationAdmission(forkRunID, baseRequest.AgentRuntime.Declarations)
	if err != nil {
		t.Fatal(err)
	}
	record := runtimemanager.PersistedAgent{Config: targetConfig, Topology: topology, Status: "active", HiredBy: "test", StartedAt: now}
	if _, err := grant.CommitAgentLifecycleTransition(ctx, runtimemanager.AgentLifecycleTransition{
		OperationID: uuid.NewString(), OperationKind: "spawn", RequestHash: uuid.NewString(), Trigger: "competition-proof",
		DiagnosticOrigin: runtimemanager.LifecycleDiagnosticOrigin{
			Owner: runtimemanager.LifecycleDiagnosticSelectedFork, Causality: runtimemanager.LifecycleDiagnosticObservation,
			SelectedFork: authority.SelectedFork, SourceRunID: admission.SourceRunID,
			ForkPoint: admission.ForkPoint, ForkEventID: admission.ForkEventID,
		},
		Identity: targetIdentity, AgentID: targetIdentity.AgentID(), ConfigRevision: targetRevision,
		TargetEpoch: 1, TargetGeneration: 1, TargetPhase: runtimemanager.AgentLifecycleRegistered, RunMode: runtimemanager.AgentRunModeStopped,
		Topology: topology, Agent: &record, Now: now,
	}); err != nil {
		t.Fatal(err)
	}
	authority.Target = runtimeeffects.UsageTarget{
		Kind:          runtimeeffects.UsageTargetAgentTurn,
		ID:            uuid.NewString(),
		RunID:         forkRunID,
		AgentID:       "selected-agent",
		AgentIdentity: targetIdentity,
		SessionID:     uuid.NewString(),
		Memory:        agentmemory.Plan{},
		FlowInstance:  targetIdentity.FlowInstance(),
	}
	providerCtx := runtimeeffects.WithLogicalOperationIdentity(
		runtimeeffects.WithController(runtimeeffects.WithAuthority(ctx, authority), liveTestCompletionController(winner.store, winner.store, winner.store, selectedForkDiscardSpendProjection{})),
		"served-standalone-authority-race",
	)
	providerCtx = managedexecution.WithAdmission(providerCtx, winner.container.admission)
	capabilitySurface, err := managedcapabilities.New(managedcapabilities.Plan{
		ActorIdentity: authority.Target.AgentIdentity, RuntimeMode: "task",
		Provider: "openai", Transport: "api", ProviderContract: "run-fork-race-test",
		Authority: managedcapabilities.Authority{
			Kind: managedcapabilities.AuthorityProviderTurn, ID: authority.Target.ID,
			ExecutionKind:        managedcapabilities.ExecutionSelectedContractFork,
			ExecutionAuthorityID: authority.SelectedFork.ExecutionID, RunID: authority.SelectedFork.ForkRunID,
			SessionID: authority.Target.SessionID, TurnOrdinal: 1,
		},
		CreatedAt: time.Unix(1, 0).UTC(),
	})
	if err != nil {
		t.Fatalf("build winning %s capability surface: %v", winner.surface, err)
	}
	providerCtx = managedcapabilities.WithContext(providerCtx, capabilitySurface)
	frame, causalEvent := selectedForkAuthorityRaceFrame(t, authority, capabilitySurface, baseRequest.LoadedSource.SourceArtifactFact)
	providerCtx = runtimecorrelation.WithSourceArtifactFact(providerCtx, baseRequest.LoadedSource.SourceArtifactFact)
	providerCtx = runtimecorrelation.WithInboundEvent(providerCtx, causalEvent)
	causalEvent, err = eventfixture.BindPayload(causalEvent)
	if err != nil {
		t.Fatal(err)
	}
	admitted, err := events.AdmitForPublish(causalEvent, events.AdmissionOptions{RequirePersistentUUIDIdentity: true})
	if err != nil {
		t.Fatal(err)
	}
	ledger, err := events.NewConnectEvaluationLedger(nil)
	if err != nil {
		t.Fatal(err)
	}
	settlement, err := events.NewDeliverySettlement(events.EventWriteNormalPublication, ledger)
	if err != nil {
		t.Fatal(err)
	}
	deliveryAuthority, err := deliverylifecycle.NewSelectedExecutionAuthority(baseRequest.LoadedSource.SourceArtifactFact, authority.ID, forkRunID, authority.SelectedFork.Generation)
	if err != nil {
		t.Fatal(err)
	}
	route := events.DeliveryRoute{Recipient: events.MustAgentDeliveryRecipient(targetIdentity.AgentID()), AgentIdentity: targetIdentity}
	scope, err := runtimeauthoractivity.BundleScopeForTarget(providerCtx, baseRequest.LoadedSource.SourceArtifactFact.BundleHash())
	if err != nil {
		t.Fatal(err)
	}
	catalog, err := winner.store.RegisterAuthorActivityEventCatalog(scope, []runtimeauthoractivity.EventDescriptor{{
		EventType: string(causalEvent.Type()), Disposition: runtimeauthoractivity.StoryDifferent,
	}})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(catalog.Release)
	publicationClaim, err := winner.store.PipelineObligations().ClaimPublication(providerCtx, causalEvent.ID())
	if err != nil {
		t.Fatal(err)
	}
	defer func() {
		if err := winner.store.PipelineObligations().Release(context.WithoutCancel(providerCtx), publicationClaim); err != nil {
			t.Error(err)
		}
	}()
	committed, err := winner.store.CommitPublication(providerCtx, bus.PublicationCommand{Commit: bus.CommitPublishRequest{
		Event: admitted, RouteSettlement: settlement, DeliveryRoutes: []events.DeliveryRoute{route},
		DeliveryAuthority: deliveryAuthority, ReplayScope: runtimepipelineobligation.ScopeDirect, PipelineClaim: publicationClaim,
	}})
	if err != nil || !committed.Acknowledged {
		t.Fatalf("commit winning provider delivery: acknowledged=%t err=%v", committed.Acknowledged, err)
	}
	claimed, err := storetest.ClaimDelivery(providerCtx, winner.store, causalEvent, route)
	if err != nil {
		t.Fatal(err)
	}
	providerCtx = deliverylifecycle.WithClaim(providerCtx, claimed.Claim)
	handle, err := runtimeeffects.BeginManagedCompletion(providerCtx, "openai_compatible", []byte("request"), frame, nil)
	if err != nil {
		t.Fatalf("winning %s authorize provider completion: %v", winner.surface, err)
	}
	if err := handle.MarkLaunched(providerCtx); err != nil {
		t.Fatalf("winning %s launch provider completion: %v", winner.surface, err)
	}
	var providerLaunches atomic.Int32
	providerLaunches.Add(1)
	if err := handle.MarkResponseObserved(providerCtx, map[string]any{"surface": winner.surface}); err != nil {
		t.Fatalf("winning %s observe provider response: %v", winner.surface, err)
	}
	inputTokens, outputTokens := int64(1), int64(1)
	capabilitySurfaceJSON, err := json.Marshal(capabilitySurface)
	if err != nil {
		t.Fatalf("marshal winning %s capability surface: %v", winner.surface, err)
	}
	if _, err := handle.SettleCompletion(providerCtx, runtimeeffects.CompletionSettlement{
		Settlement: runtimeeffects.Settlement{State: runtimeeffects.StateSettled, Evidence: map[string]any{"surface": winner.surface}},
		Usage: runtimeeffects.CompletionUsage{
			ResolvedModel: "test-model",
			Exactness:     runtimeeffects.CompletionUsageExact,
			InputTokens:   &inputTokens,
			OutputTokens:  &outputTokens,
		},
		AgentTurn: &runtimeeffects.CompletionAgentTurn{
			TurnID: authority.Target.ID, RunID: forkRunID, AgentID: authority.Target.AgentID,
			Identity:  targetIdentity,
			SessionID: authority.Target.SessionID, Memory: authority.Target.Memory,
			FlowInstance: authority.Target.FlowInstance, TriggerEventID: frame.Turn.Event.ID, TriggerEventType: frame.Turn.Event.Type, ParseOK: true,
			CapabilitySurfaceID: capabilitySurface.ID, CapabilitySurface: capabilitySurfaceJSON,
		},
		Spend: runtimeeffects.CompletionSpend{
			FlowInstance: authority.Target.FlowInstance, AgentID: authority.Target.AgentID,
			AgentIdentity: targetIdentity,
			Model:         "test-model", ModelAlias: "regular", BackendProfile: "test",
			Provider: "test", Transport: "http", ResolvedModel: "test-model",
			InvocationType: "test",
		},
		Now: time.Now().UTC(),
	}); err != nil {
		t.Fatalf("winning %s settle provider completion: %v", winner.surface, err)
	}
	if providerLaunches.Load() != 1 {
		t.Fatalf("provider launches = %d, want 1", providerLaunches.Load())
	}
	if err := winner.container.Quiesce(ctx); err != nil {
		t.Fatalf("quiesce winning %s container: %v", winner.surface, err)
	}
	if err := winner.container.Close(ctx); err != nil {
		t.Fatalf("close winning %s container: %v", winner.surface, err)
	}

	var authorities, attempts, reservations int
	if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM run_fork_selected_contract_runtime_executions WHERE fork_run_id=$1::uuid AND generation=1 AND state='closed'`, forkRunID).Scan(&authorities); err != nil {
		t.Fatalf("count served/standalone authority rows: %v", err)
	}
	if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM runtime_external_effect_attempts a JOIN runtime_external_effect_operations o ON o.operation_id=a.operation_id WHERE o.selected_execution_id=$1::uuid AND a.state='settled'`, proof.RuntimeExecutionID).Scan(&attempts); err != nil {
		t.Fatalf("count served/standalone completion attempts: %v", err)
	}
	if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM runtime_effect_budget_reservations WHERE attempt_id=$1::uuid`, handle.Attempt().AttemptID).Scan(&reservations); err != nil {
		t.Fatalf("count no-cap completion reservations: %v", err)
	}
	if authorities != 1 || attempts != 1 || reservations != 0 {
		t.Fatalf("served/standalone authority evidence authorities=%d attempts=%d reservations=%d, want 1/1/0", authorities, attempts, reservations)
	}
}

